window.products.push({"id":1141916,"name":"Panasonic Ceramic Cordless Freestyle Iron, Charcoal","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71kScC+U6+L._AC_SL1500_.jpg","description":"Panasonic 360º Ceramic Cordless Freestyle Iron Whether it's a last-minute presentation at work, an impromptu dinner party or an unexpected visit from the in-laws, this freestyle iron helps you smooth out at least some of life's wrinkles. The vertical-steam option allows you to press curtains without taking them off the rod, while the cordless design lets you handle pressing issues without getting tangled up. And the expansive surface means you'll be finished quicker, leaving your admirers to wonder how you manage it all so effortlessly. What You Get Iron Charging base Detachable water tank Cover case Instruction manual","images":["https://m.media-amazon.com/images/I/71kScC+U6+L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Panasonic","source_asin":"B01B22JZZA","category_path":"Home & Kitchen"},"sku":"BM-1141916","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01B22JZZA","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01B22JZZA","price_pending":true,"merchant_ready":false});
